import { AutoCaptureEngine } from "../autocapture/AutoCaptureEngine";
import { SessionManager } from "./SessionManager";
import { EventQueue } from "./EventQueue";
import { Transport } from "./Transport";
import { Batcher } from "./Batcher";
import { getPageContext } from "./PageContext";
import { captureEnvironmentSnapshot } from "./EnvironmentContext";
import { generateId } from "./ids";
import { resolveConfig } from "./defaultConfig";
import type { AnalyticsConfig, ResolvedAnalyticsConfig } from "../types/config";
import type {
  AnalyticsEvent,
  AnyPayload,
  ClickEventPayload,
  ScrollEventPayload,
  RageClickEventPayload,
  FunnelEventPayload,
  CustomEventPayload,
  IdentifyEventPayload,
  SessionStartEventPayload,
  EventType,
} from "../types/events";
import type { FunnelStep } from "../types/funnel";
import { RouteObserver } from "../dom/RouteObserver";
import { SessionActivityMonitor } from "./SessionActivityMonitor";
import { loadEditorRuntime, loadExperienceRuntime } from "../experiences/loadRuntimes";
import { clearEditorContinuation, readEditorContinuation } from "../experiences/editorContinuation";
import { exchangeEditorSession, prefetchEditorDraft } from "../experiences/editorFastStart";
import type {
  AnalyticsRuntimeProviders,
  EditorContinuation,
  EditorControllerRuntime,
  ExperienceLoaderRuntime,
} from "../experiences/runtimeInterfaces";
import { processPendingSdkTasks } from "./SdkConnectionVerifier";

/**
 * The core SDK instance. Owns configuration, session identity, the
 * autocapture engine, and the delivery pipeline. This is the only class
 * that is allowed to move events from "captured" to "sent" - collectors
 * never talk to the network directly.
 */
export class Analytics {
  private config!: ResolvedAnalyticsConfig;
  private session!: SessionManager;
  private engine!: AutoCaptureEngine;
  private queue!: EventQueue;
  private transport!: Transport;
  private batcher!: Batcher;
  private routeObserver = new RouteObserver();
  private activityMonitor: SessionActivityMonitor | null = null;
  private experiences: ExperienceLoaderRuntime | null = null;
  private pendingExperienceLaunches: string[] = [];
  private deliveryRefreshPending = false;
  private deliveryRefreshRunning = false;
  private deliveredTriggers = new Set<string>();
  private deliveryIdentityGeneration = 0;
  private editor: EditorControllerRuntime | null = null;
  private editorMode = false;
  private editorAttempted = false;

  private debugEnabled = false;
  private initialized = false;
  private running = false;
  private generation = 0;
  private unsubscribers: Array<() => void> = [];

  constructor(private runtimeProviders: AnalyticsRuntimeProviders = {}) {}

  init(userConfig: AnalyticsConfig): void {
    if (this.initialized) {
      this.log("already initialized, ignoring duplicate init()");
      return;
    }

    this.config = resolveConfig(userConfig);
    this.debugEnabled = !!this.config.debug;
    const generation = ++this.generation;

    const editorToken = new URL(location.href).searchParams.get("movcues_editor_token");
    const editorContinuation = editorToken ? null : readEditorContinuation();
    if ((editorToken || editorContinuation) && !this.editorAttempted) {
      // Do not create a SessionManager, collectors, or a page view until the
      // editor token or continuation has been validated by the draft endpoint.
      this.initialized = true;
      this.editorAttempted = true;
      void this.initializeEditor(editorToken, editorContinuation, userConfig, generation);
      return;
    }

    if (this.config.respectDoNotTrack && isDoNotTrackEnabled()) {
      this.log("Do Not Track enabled - autocapture disabled");
      this.initialized = true;
      return;
    }

    void processPendingSdkTasks(this.config.endpoint, this.config.siteId);

    this.session = new SessionManager(this.config.sessionInactivityMs);
    this.transport = new Transport(this.config.endpoint, this.config.siteId);
    this.queue = new EventQueue({ maxQueueSize: this.config.queue.maxQueueSize });
    this.batcher = new Batcher(this.queue, this.transport, this.config.queue, (msg, ...args) =>
      this.log(msg, ...args), (events) => this.onEventsDelivered(events)
    );
    this.engine = new AutoCaptureEngine(this.config);
    this.activityMonitor = new SessionActivityMonitor(this.session);
    this.wireCollectorsToPipeline();

    this.initialized = true;
    this.log("initialized", { siteId: this.config.siteId });

    this.unsubscribers.push(this.routeObserver.onChange(() => this.onRouteChange()));
    this.routeObserver.start();

    this.start();

    // Fire the initial page view + funnel evaluation.
    this.trackPageView();

    if (this.config.experiences.enabled) {
      void this.initializeExperiences(generation);
    }
  }

  start(): void {
    if (!this.initialized || this.editorMode || this.running || !this.engine) return;
    this.running = true;
    this.engine.start();
    this.activityMonitor?.start();
    this.batcher.start();
    this.log("autocapture started");
  }

  stop(): void {
    if (!this.running) return;
    this.running = false;
    this.engine.stop();
    this.activityMonitor?.stop();
    this.batcher.stop();
    this.log("autocapture stopped");
  }

  destroy(): void {
    this.generation++;
    this.stop();
    this.routeObserver.stop();
    for (const unsub of this.unsubscribers) unsub();
    this.unsubscribers = [];
    this.queue?.clear();
    this.experiences?.destroy();
    this.experiences = null;
    this.pendingExperienceLaunches = [];
    this.deliveryRefreshPending = false;
    this.deliveredTriggers.clear();
    this.activityMonitor = null;
    this.editor?.destroy();
    this.editor = null;
    this.editorMode = false;
    this.editorAttempted = false;
    this.initialized = false;
    this.log("destroyed");
  }

  event(name: string, properties?: Record<string, unknown>): void {
    if (!this.requireInit()) return;
    const payload: CustomEventPayload = { name, properties };
    this.enqueueEvent("custom", payload);
    this.engine.funnel.onCustomEvent(name);
    this.experiences?.onCustomEvent(name);
    // Custom events retain normal analytics batching. Acknowledgment refreshes
    // eligibility when that batch (or its retry) has committed.
    this.log(`event: ${name}`, properties);
  }

  identify(userId: string, attributes?: Record<string, unknown>): void {
    if (!this.requireInit()) return;
    const previous = this.session.getIdentifiedUserId();
    this.session.identify(userId);
    if (previous !== userId) {
      this.deliveryIdentityGeneration++;
      this.deliveredTriggers.clear();
      this.experiences?.resetContext?.(previous === null);
    }
    const payload: IdentifyEventPayload = { userId, traits: attributes };
    this.enqueueEvent("identify", payload);
    void this.refreshExperiencesAfterFlush();
    this.log(`identify: ${userId}`, attributes);
  }

  /** Clear the active identity and begin future activity as a new visitor. */
  reset(): void {
    if (!this.requireInit()) return;
    this.session.reset();
    this.deliveryIdentityGeneration++;
    this.deliveredTriggers.clear();
    this.pendingExperienceLaunches = [];
    this.experiences?.resetContext?.();
    this.trackPageView();
    void this.refreshExperiencesAfterFlush();
    this.log("identity reset");
  }

  page(): void {
    if (!this.requireInit()) return;
    this.trackPageView();
  }

  /** Explicitly launch a published Guide, bypassing automatic targeting. */
  launchExperience(experienceId: string): void {
    if (!this.requireInit() || !experienceId) return;
    if (this.experiences?.launchExperience) void this.experiences.launchExperience(experienceId);
    else this.pendingExperienceLaunches.push(experienceId);
  }

  defineFunnel(name: string, steps: FunnelStep[]): void {
    if (!this.requireInit()) return;
    this.engine.funnel.define(name, steps);
    this.log(`funnel defined: ${name}`, steps);
    // Evaluate immediately in case the current page already matches step 1.
    this.engine.funnel.onPageView(location.pathname);
  }

  enableDebug(): void {
    this.debugEnabled = true;
    this.log("debug mode enabled");
  }

  disableDebug(): void {
    this.log("debug mode disabled");
    this.debugEnabled = false;
  }

  // -------------------------------------------------------------------
  // Internal wiring
  // -------------------------------------------------------------------

  private requireInit(): boolean {
    if (!this.initialized || this.editorMode || !this.session) {
      // eslint-disable-next-line no-console
      console.warn("[Analytics] call analytics.init(config) before using this method");
      return false;
    }
    return true;
  }

  private async initializeEditor(editorToken: string | null, continuation: EditorContinuation | null, userConfig: AnalyticsConfig, generation: number): Promise<void> {
    try {
      performance.mark?.("movcues:editor:start");
    } catch { /* Performance marks are diagnostic-only. */ }
    try {
      // Only the shipped editor runtime supports prefetched credentials. Custom
      // runtime providers retain their original start/resume contract.
      const useFastStart = !this.runtimeProviders.editor && !this.runtimeProviders.loadEditor;
      const exchangePromise = editorToken && useFastStart ? exchangeEditorSession(this.config.endpoint, editorToken) : null;
      const draftPromise = !editorToken && continuation && useFastStart
        ? prefetchEditorDraft(this.config.endpoint, continuation.session)
        : null;
      const runtimePromise = this.runtimeProviders.editor
        ? Promise.resolve(this.runtimeProviders.editor)
        : this.runtimeProviders.loadEditor
          ? this.runtimeProviders.loadEditor()
          : loadEditorRuntime(this.config.editorRuntimeBundleUrl);
      const [runtime, exchange, prefetchedDraft] = await Promise.all([
        runtimePromise,
        exchangePromise ?? Promise.resolve(null),
        draftPromise ?? Promise.resolve(null),
      ]);
      if (!this.initialized || generation !== this.generation) return;
      if (!runtime) {
        this.fallbackFromEditor(userConfig, generation);
        return;
      }

      const editor = runtime.createController(this.config.endpoint);
      let started = false;
      if (editorToken) {
        // Do not retry a consumed, single-use token through the old start() path.
        started = exchangePromise
          ? Boolean(exchange && editor.startAuthenticatedSession && await editor.startAuthenticatedSession(exchange.session, exchange.draft))
          : await editor.start(editorToken);
      } else if (continuation) {
        started = prefetchedDraft && editor.resumeWithDraft
          ? await editor.resumeWithDraft(continuation, prefetchedDraft)
          : await editor.resume(continuation);
      }
      if (!this.initialized || generation !== this.generation) {
        editor.destroy();
        return;
      }

      if (started) {
        this.editor = editor;
        this.editorMode = true;
        try {
          performance.mark?.("movcues:editor:ready");
          performance.measure?.("movcues:editor:startup", "movcues:editor:start", "movcues:editor:ready");
        } catch { /* Performance marks are diagnostic-only. */ }
        this.log("experience editor mode initialized");
        return;
      }

      editor.destroy();
      this.fallbackFromEditor(userConfig, generation);
    } catch {
      this.fallbackFromEditor(userConfig, generation);
    }
  }

  private fallbackFromEditor(userConfig: AnalyticsConfig, generation: number): void {
    if (!this.initialized || generation !== this.generation) return;
    // Invalid/expired tokens and editor bundle failures retain the established
    // secure failure path: no editor mounts and the page becomes a normal visit.
    clearEditorContinuation();
    this.initialized = false;
    this.init(userConfig);
  }

  private async initializeExperiences(generation: number): Promise<void> {
    try {
      const runtime = this.runtimeProviders.experiences ?? await loadExperienceRuntime(this.config.experienceRuntimeBundleUrl);
      if (!runtime || !this.initialized || this.editorMode || generation !== this.generation) return;
      this.experiences = runtime.createLoader(
        this.config.endpoint,
        this.config.siteId,
        this.session,
        (name) => this.event(name)
      );
      await this.experiences.evaluate();
      for (const id of this.pendingExperienceLaunches.splice(0)) void this.experiences.launchExperience?.(id);
      void this.drainDeliveryRefresh();
    } catch {
      // Experience delivery is isolated from analytics and host application code.
    }
  }

  private wireCollectorsToPipeline(): void {
    const bus = this.engine.bus;

    this.unsubscribers.push(
      bus.on<ClickEventPayload>("click", (p) => {
        // Raw clicks still reach RageClickDetector through the click:raw topic.
        if (!p.interactive) return;
        this.enqueueEvent("click", p);
        this.log("click captured", p.element.selector);
      })
    );

    this.unsubscribers.push(
      bus.on<ScrollEventPayload>("scroll:milestone", (p) => {
        this.enqueueEvent("scroll", p);
        this.log(`scroll milestone: ${p.milestone}%`);
      })
    );

    this.unsubscribers.push(
      bus.on<RageClickEventPayload>("rage_click", (p) => {
        this.enqueueEvent("rage_click", p);
        this.log("rage click detected", p);
      })
    );

    this.unsubscribers.push(
      bus.on<FunnelEventPayload>("funnel", (p) => {
        this.enqueueEvent("funnel", p);
        this.log(`funnel step completed: ${p.funnelName} [${p.stepIndex}] (${p.status})`);
      })
    );
  }

  private trackPageView(): void {
    this.enqueueEvent("page_view", { title: document.title });
    this.engine.funnel.onPageView(location.pathname);
  }

  private onRouteChange(): void {
    if (this.running) {
      this.session.newPageView();
      this.engine.onRouteChange(location.pathname);
      this.trackPageView();
      this.experiences?.onRouteChange();
      void this.refreshExperiencesAfterFlush();
    }
    this.log("route changed", location.pathname);
  }

  private enqueueEvent<T extends AnyPayload>(type: EventType, payload: T): void {
    this.session.touch();
    if (this.session.consumeSessionStarted()) {
      // Emitted before the event that triggered it, so a session's
      // first row in the log is always its environment context - see
      // EnvironmentContext.ts. touch() above already brought the
      // session id/lastActivity up to date, so this call doesn't
      // re-touch or risk re-triggering itself.
      this.buildAndEnqueue<SessionStartEventPayload>("session_start", captureEnvironmentSnapshot());
    }
    this.buildAndEnqueue(type, payload);
  }

  private async refreshExperiencesAfterFlush(): Promise<void> {
    // Completion alone is not an ingestion acknowledgment. Only onDelivered
    // schedules membership refreshes, including successful timer-driven retries.
    if (this.batcher && this.config.experiences.enabled) await this.batcher.flush();
  }

  private onEventsDelivered(events: readonly AnalyticsEvent[]): void {
    if (!this.initialized || !this.config.experiences.enabled) return;
    for (const event of events) {
      if (event.anonymousId !== this.session.getAnonymousId() || event.sessionId !== this.session.getSessionId()) continue;
      if (event.type === "custom" && event.page.url === location.href && event.pageViewId === this.session.getPageViewId() && Date.now() - event.timestamp <= 30_000) {
        this.deliveredTriggers.add((event.payload as CustomEventPayload).name);
        while (this.deliveredTriggers.size > 20) this.deliveredTriggers.delete(this.deliveredTriggers.values().next().value!);
      }
      if (["identify", "custom", "page_view", "session_start"].includes(event.type)) this.deliveryRefreshPending = true;
    }
    void this.drainDeliveryRefresh();
  }

  private async drainDeliveryRefresh(): Promise<void> {
    if (this.deliveryRefreshRunning || !this.experiences) return;
    const generation = this.generation;
    this.deliveryRefreshRunning = true;
    try {
      while (this.initialized && generation === this.generation && this.experiences && this.deliveryRefreshPending) {
        this.deliveryRefreshPending = false;
        const identityGeneration = this.deliveryIdentityGeneration;
        const triggers = [...this.deliveredTriggers]; this.deliveredTriggers.clear();
        await this.experiences.evaluate();
        for (const trigger of triggers) {
          if (generation !== this.generation || identityGeneration !== this.deliveryIdentityGeneration || !this.initialized) break;
          await this.experiences?.evaluate(trigger);
        }
      }
    } catch {
      // A failed delivery request must never reject into host analytics.
    } finally {
      this.deliveryRefreshRunning = false;
      if (generation !== this.generation && this.deliveryRefreshPending) void this.drainDeliveryRefresh();
    }
  }

  private buildAndEnqueue<T extends AnyPayload>(type: EventType, payload: T): void {
    const event: AnalyticsEvent<T> = {
      eventId: generateId("evt"),
      type,
      timestamp: Date.now(),
      anonymousId: this.session.getAnonymousId(),
      sessionId: this.session.getSessionId(),
      pageViewId: this.session.getPageViewId(),
      page: getPageContext(),
      payload,
    };
    this.batcher.enqueue(event as AnalyticsEvent<AnyPayload>);
  }

  /** Called by bootstrap on visibilitychange/pagehide for unload-safe delivery. */
  flushOnUnload(): void {
    if (!this.initialized || this.editorMode || !this.batcher) return;
    this.batcher.flushSync();
  }

  private log(message: string, ...args: unknown[]): void {
    if (!this.debugEnabled) return;
    // eslint-disable-next-line no-console
    console.log(`[Analytics] ${message}`, ...args);
  }
}

function isDoNotTrackEnabled(): boolean {
  const dnt =
    (navigator as any).doNotTrack || (window as any).doNotTrack || (navigator as any).msDoNotTrack;
  return dnt === "1" || dnt === "yes";
}
